  // 聊天内容生成提示词与比例建议
  let promptCallBody=null;
  globalThis.fetch=async(url,options)=>{
   promptCallBody=JSON.parse(options.body);
   return new Response(JSON.stringify({
    choices:[{message:{content:JSON.stringify({prompt:'阳光洒在金色的沙滩上，少女穿着白色连衣裙，海风吹拂着她的长发',aspect_ratio:'16:9',title:'海边少女'})}}]
   }));
  };
  const imgPromptRes=response();
  await routes.get('POST /api/android/media/image-prompt')(req({
   text:'她站在海边，迎着落日余晖轻轻微笑。',
   context:[{name:'用户',text:'我们去海边散步吧。'}],
   styleHint:'日系清新插画',
   scopeId:'card:IMG_TEST'
  }),imgPromptRes);
  assert.equal(imgPromptRes.statusCode,200);
  assert.equal(imgPromptRes.result.aspect_ratio,'16:9');
  assert.equal(imgPromptRes.result.title,'海边少女');
  assert.ok(imgPromptRes.result.prompt.includes('沙滩'));
  assert.ok(promptCallBody.messages[1].content.includes('日系清新插画'));

  // 不支持的比例自动回退为 1:1
  globalThis.fetch=async()=>new Response(JSON.stringify({
   choices:[{message:{content:JSON.stringify({prompt:'星空夜景',aspect_ratio:'99:99',title:'夜景'})}}]
  }));
  const fallbackRatioRes=response();
  await routes.get('POST /api/android/media/image-prompt')(req({text:'看星空',scopeId:'card:IMG_TEST'}),fallbackRatioRes);
  assert.equal(fallbackRatioRes.statusCode,200);
  assert.equal(fallbackRatioRes.result.aspect_ratio,'1:1');

  // 生图并持久化存入当前角色卡历史
  const fakePngBase64='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9ZKZsAAAAASUVORK5CYII=';
  globalThis.fetch=async(url,options)=>new Response(JSON.stringify({
   candidates:[{content:{parts:[{inlineData:{mimeType:'image/png',data:fakePngBase64}}]}}]
  }));
  const genImgRes=response();
  await routes.get('POST /api/android/media/generate-image')(req({
   prompt:'阳光洒在金色的沙滩上',
   aspect_ratio:'16:9',
   scopeId:'card:IMG_A',
   source:{label:'消息#1',excerpt:'她站在海边'}
  }),genImgRes);
  assert.equal(genImgRes.statusCode,200);
  assert.equal(genImgRes.result.format,'png');
  assert.ok(genImgRes.result.historyId);

  // 查看历史与卡片隔离
  const histResA=response();
  await routes.get('GET /api/android/media/image-history')({...req({}),query:{scope:'card:IMG_A'}},histResA);
  assert.equal(histResA.statusCode,200);
  assert.equal(histResA.result.images.length,1);
  assert.equal(histResA.result.images[0].prompt,'阳光洒在金色的沙滩上');
  assert.equal(histResA.result.images[0].ratio,'16:9');
  assert.equal(histResA.result.images[0].source.label,'消息#1');
  assert.ok(histResA.result.images[0].url.includes(genImgRes.result.historyId));

  const histResB=response();
  await routes.get('GET /api/android/media/image-history')({...req({}),query:{scope:'card:IMG_B'}},histResB);
  assert.equal(histResB.statusCode,200);
  assert.equal(histResB.result.images.length,0);

  // 读取图片文件内容
  const imgFileRes=response();
  await routes.get('GET /api/android/media/image-history/:id/file')({...req({}),params:{id:genImgRes.result.historyId},query:{scope:'card:IMG_A'}},imgFileRes);
  assert.equal(imgFileRes.statusCode,200);
  assert.deepEqual(imgFileRes.result,Buffer.from(fakePngBase64,'base64'));

  // 删除图片记录与文件
  const delImgRes=response();
  await routes.get('POST /api/android/media/image-history/delete')(req({id:genImgRes.result.historyId,scopeId:'card:IMG_A'}),delImgRes);
  assert.equal(delImgRes.statusCode,200);
  assert.equal(delImgRes.result.ok,true);

  const histAfterDel=response();
