  assert.equal(histAfterDel.result.images.length,0);

  const fileAfterDel=response();
  await routes.get('GET /api/android/media/image-history/:id/file')({...req({}),params:{id:genImgRes.result.historyId},query:{scope:'card:IMG_A'}},fileAfterDel);
  assert.equal(fileAfterDel.statusCode,404);

